fields.InputDefinition:
{
  "goal": "Open the Lists app using the application switcher dropdown next to the logo (NOT the Ctrl+K search box). In the Lists section, use the Create list action to create a new list named 'Regression Test List 2' for the People entity — when choosing the entity for the list, select the one named exactly 'People' (NOT 'Person Job Functions', 'Member Profiles', or any other similar entity). Then add at least one People record (for example Elena Rodriguez) to the list. Confirm success by reaching a state where the new list 'Regression Test List 2' exists and displays the added People record. Pages can take 10-30s to load in this resource-constrained env - wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
